import{_ as a,o as t,c as n,a0 as i}from"./chunks/framework.DoRPXVp_.js";const h=JSON.parse('{"title":"AI Capabilities Overview","description":"","frontmatter":{"title":"AI Capabilities Overview"},"headers":[],"relativePath":"ai/index.md","filePath":"ai/index.md"}'),s={name:"ai/index.md"};function r(o,e,l,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="ai-capabilities-overview" tabindex="-1">AI Capabilities Overview <a class="header-anchor" href="#ai-capabilities-overview" aria-label="Permalink to &quot;AI Capabilities Overview&quot;">​</a></h1><p>Lattice provides a <strong>five-layer AI capability model</strong> that spans from developer productivity to enterprise compliance. All AI features are accessible through the built-in dashboard, the MCP protocol (for Claude Desktop / Claude Code / Cursor), and REST APIs.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------------------------------------------------------------+</span></span>
<span class="line"><span>|  Layer 5: Compliance-as-Conversation                            |</span></span>
<span class="line"><span>|  SOC2/PCI-DSS/HIPAA compliance report generation                |</span></span>
<span class="line"><span>+-----------------------------------------------------------------+</span></span>
<span class="line"><span>|  Layer 4: Time-Travel Network Debugging                         |</span></span>
<span class="line"><span>|  Network state snapshots + AI root cause analysis               |</span></span>
<span class="line"><span>+-----------------------------------------------------------------+</span></span>
<span class="line"><span>|  Layer 3: Network Intent Engine (Pro)                           |</span></span>
<span class="line"><span>|  Natural language intent → CRD change plans                     |</span></span>
<span class="line"><span>+-----------------------------------------------------------------+</span></span>
<span class="line"><span>|  Layer 2: Zero-Trust for AI Agent Fleets                        |</span></span>
<span class="line"><span>|  AI agent auto-enrollment, TTL identity, network isolation      |</span></span>
<span class="line"><span>+-----------------------------------------------------------------+</span></span>
<span class="line"><span>|  Layer 1: MCP Server + AI ChatOps Write Tools                   |</span></span>
<span class="line"><span>|  Entry point and execution engine for all upper layers          |</span></span>
<span class="line"><span>+-----------------------------------------------------------------+</span></span></code></pre></div><h2 id="layer-1-—-mcp-server-chatops-details" tabindex="-1">Layer 1 — MCP Server + ChatOps (<a href="./mcp-server">Details</a>) <a class="header-anchor" href="#layer-1-—-mcp-server-chatops-details" aria-label="Permalink to &quot;Layer 1 — MCP Server + ChatOps ([Details](./mcp-server))&quot;">​</a></h2><p>The foundation layer. Exposes Lattice&#39;s full network management capability via the <strong>Model Context Protocol (MCP)</strong>.</p><ul><li>Read tools: list peers, policies, networks, check connectivity</li><li>Write tools: create/delete peers, manage policies (with human-in-the-loop approval)</li><li>Works with Claude Desktop, Claude Code, Cursor, and any MCP client</li><li>All write operations go through <code>WorkflowService</code> for approval by default</li></ul><h2 id="layer-2-—-zero-trust-ai-agent-networking-details" tabindex="-1">Layer 2 — Zero-Trust AI Agent Networking (<a href="./agent-enrollment">Details</a>) <a class="header-anchor" href="#layer-2-—-zero-trust-ai-agent-networking-details" aria-label="Permalink to &quot;Layer 2 — Zero-Trust AI Agent Networking ([Details](./agent-enrollment))&quot;">​</a></h2><p>AI agents get their own WireGuard identity with time-bound enrollment and network isolation.</p><ul><li><strong>POST /api/v1/agent-enroll</strong> — agents self-register with TTL and policy preset</li><li>Policy presets: <code>sandboxed</code>, <code>coordinator</code>, <code>isolated</code></li><li>TTL-based auto-destruction via Manager reconciler</li><li>Python SDK (<code>lattice-sdk-python</code>) for easy integration with LangGraph, AutoGen, Claude agent-sdk</li></ul><h2 id="layer-3-—-network-intent-engine-pro-details" tabindex="-1">Layer 3 — Network Intent Engine (Pro) (<a href="./intent-engine">Details</a>) <a class="header-anchor" href="#layer-3-—-network-intent-engine-pro-details" aria-label="Permalink to &quot;Layer 3 — Network Intent Engine (Pro) ([Details](./intent-engine))&quot;">​</a></h2><p>Describe network changes in natural language. Lattice produces a structured CRD change plan for review.</p><ul><li>Two-stage LLM pipeline: structured intent extraction → human-readable diff</li><li><code>POST /api/v1/ai/intent/plan</code> — preview changes without applying</li><li><code>POST /api/v1/ai/intent/apply</code> — execute approved plans through WorkflowService</li><li>Risk level assessment before any change is applied</li></ul><h2 id="layer-4-—-time-travel-network-debugging-pro-details" tabindex="-1">Layer 4 — Time-Travel Network Debugging (Pro) (<a href="./debugging">Details</a>) <a class="header-anchor" href="#layer-4-—-time-travel-network-debugging-pro-details" aria-label="Permalink to &quot;Layer 4 — Time-Travel Network Debugging (Pro) ([Details](./debugging))&quot;">​</a></h2><p>Automatic network state snapshots let you debug any past state with AI assistance.</p><ul><li>Snapshots triggered by policy changes, peer online/offline, manual, or scheduled</li><li>Diff any two snapshots to see exactly what changed</li><li>AI-powered root cause analysis: ask questions about past state</li><li>Get/snapshot/diff MCP tools for Claude-assisted debugging</li></ul><h2 id="layer-5-—-compliance-as-conversation-pro-details" tabindex="-1">Layer 5 — Compliance-as-Conversation (Pro) (<a href="./compliance">Details</a>) <a class="header-anchor" href="#layer-5-—-compliance-as-conversation-pro-details" aria-label="Permalink to &quot;Layer 5 — Compliance-as-Conversation (Pro) ([Details](./compliance))&quot;">​</a></h2><p>Generate compliance reports and evidence packages from your Lattice network state.</p><ul><li>Framework support: SOC2 Type II, PCI-DSS, HIPAA</li><li>Automated control verification against network policies and change history</li><li>Downloadable evidence packages (ZIP) with SHA256 attestation</li><li>Executive summaries generated by AI for CISO review</li></ul><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>All AI features share the same foundation. To get started:</p><ol><li><a href="./../config/reference#ai">Enable the AI module</a> in your <code>lattice.yaml</code></li><li>Configure your LLM provider (Anthropic or OpenAI-compatible)</li><li>Connect via the <a href="./mcp-server">MCP Server</a> or use the built-in dashboard Chat interface</li></ol><p>See the <a href="./mcp-server">MCP Server setup guide</a> for Claude Desktop / Claude Code integration.</p>`,22)])])}const g=a(s,[["render",r]]);export{h as __pageData,g as default};
